 for(const s of rows){
  const id=s.therapeuticArea||'unclassified';
  let g=by.get(id);if(!g){g={id,label:areaLabel(id),group:areaGroup(id),value:0,companies:0,holders:0,topCount:0,maxWeight:0,lead:null,names:[]};by.set(id,g);}
  g.value+=s.value;g.companies++;g.holders+=s.breadth;g.topCount+=s.topCount;g.names.push(s);
  if(s.maxWeight>=g.maxWeight){g.maxWeight=s.maxWeight;g.lead=s;}
 }
 for(const g of by.values()){g.share=total?g.value/total*100:0;g.names.sort((a,b)=>b.maxWeight-a.maxWeight);}
