function spark(series){if(!series?.length)return '<div class="empty">Price history unavailable</div>';const v=series.slice(-126),lo=Math.min(...v.map(p=>p.close)),hi=Math.max(...v.map(p=>p.close));const pts=v.map((p,i)=>`${12+i/(v.length-1||1)*776},${126-(p.close-lo)/(hi-lo||1)*108}`).join(' ');return `<svg class="spark" viewBox="0 0 800 140" role="img" aria-label="Six-month daily closing prices"><polyline points="${pts}" fill="none" stroke="#008678" stroke-width="2.5" vector-effect="non-scaling-stroke"/></svg>`;}
function openDetail(key){
 detailKey=key;
 const s=universe().find(s=>s.key===key);if(!s)return {error:'Company unavailable for selected quarter'};const t=s.tech,m=s.market,st=m.statistics||{},dialog=document.getElementById('detail');const owners=D.owners?.[s.ticker||s.key];const others=owners?.period===state.period?owners.holders.filter(h=>!D.funds.some(f=>f.cik===h.cik)):[];
 const stat=k=>st[k]||'Unavailable';const stale=t.date&&(new Date(m.retrieved)-new Date(t.date))/86400000>7;
 dialog.innerHTML=`<div class="detailhead"><div><span class="eyebrow" style="color:#6bd8c5">${esc(s.category)}${s.therapeuticArea?` · ${esc(areaLabel(s.therapeuticArea))}`:''}</span><h2 id="detail-title">${esc(s.ticker||s.key)} <span style="font-size:16px;font-weight:400">${esc(s.name)}</span></h2><p>Ownership snapshot ${esc(state.period)} · ${s.breadth} selected managers</p></div><button id="close" aria-label="Close company profile">✕</button></div><div class="detailbody"><div class="detailstats">${[['Largest fund allocation',pct(s.maxWeight,2)],['Average across funds',pct(s.meanWeight,2)],['Combined reported value',usd(s.value)],['Top-'+state.depth+' appearances',s.topCount]].map(([l,v])=>`<div class="metric"><label>${l}</label><strong>${v}</strong></div>`).join('')}</div>
 <h3>Who in your universe holds it?</h3><p class="definition">${esc(s.holders[0].fundName)} has the largest portfolio allocation at ${pct(s.maxWeight,2)}. ${s.breadth} of ${filings().length} reporting managers disclose this company. These are quarter-end holdings; the identity of today’s buyers and sellers is unavailable.</p><div class="tablewrap"><table class="detailtable"><thead><tr><th>Manager / equity rank</th><th>13F weight</th><th>Value</th><th>Shares</th><th>QoQ shares</th><th>Source</th></tr></thead><tbody>${s.holders.map(h=>`<tr><td>${esc(h.fundName)} ${badge(h)}</td><td>${pct(h.weight,2)}</td><td>${usd(h.value)}</td><td>${num(h.shares)}</td><td class="${tone(h.delta)}">${h.delta!=null?signed(h.delta):h.status==='Newly reported'?'Newly reported':h.status==='Identity changed'?'Review identity':'—'}</td><td><a href="${esc(h.xml||h.sec)}" target="_blank" rel="noopener">SEC ↗</a> · <a href="${esc(h.source)}" target="_blank" rel="noopener">Table ↗</a></td></tr>`).join('')}</tbody></table></div>
 ${s.holders.some(h=>h.mappingNote)?`<div class="notice">${[...new Set(s.holders.map(h=>h.mappingNote).filter(Boolean))].map(esc).join('<br>')}</div>`:''}
 <h3>Other institutional shareholders</h3>${others.length?`<div class="tablewrap"><table class="detailtable"><thead><tr><th>Reporting institution</th><th>Reported value</th><th>Shares</th><th>Filing</th></tr></thead><tbody>${others.map(h=>`<tr><td>${esc(h.name)}</td><td>${usd(h.value)}</td><td>${num(h.shares)}</td><td><a href="${esc(h.source)}" target="_blank" rel="noopener">13F ↗</a></td></tr>`).join('')}</tbody></table></div><p class="definition">All ${others.length} other managers among the source’s top 30 holders for ${esc(owners.period)}${owners.reportedHolderCount?` (${num(owners.reportedHolderCount)} reporting holders in total)`:''}. These institutions provide context and do not enter your screening universe. Source: ${owners.sources.map(u=>`<a href="${esc(u)}" target="_blank" rel="noopener">13f.info ↗</a>`).join(' · ')}. Affiliated reporting entities can overlap; no total ownership percentage is inferred. A manager’s name alone does not establish active, passive, retail, or current trading activity.</p>`:'<p class="definition">Broader holder detail is unavailable for this company and selected quarter.</p>'}
 <h3>Shareholder structure & short positioning</h3><div class="twocol"><div>${[['Institutional ownership','Owned by Institutions (%)'],['Insider ownership','Owned by Insiders (%)'],['Shares outstanding','Shares Outstanding'],['Float','Float']].map(([l,k])=>`<div class="keyval"><span>${l}</span><strong>${esc(stat(k))}</strong></div>`).join('')}</div><div>${[['Short interest','Short Interest'],['Short interest / float','Short % of Float'],['Days to cover','Short Ratio (days to cover)'],['Prior short interest','Short Previous Month']].map(([l,k])=>`<div class="keyval"><span>${l}</span><strong>${esc(stat(k))}</strong></div>`).join('')}</div></div><p class="definition">${m.statisticsSource?`<a href="${esc(m.statisticsSource)}" target="_blank" rel="noopener">Stock Analysis statistics ↗</a> · retrieved ${esc((m.statisticsRetrieved||m.retrieved)?.slice(0,10))}. Provider observations can have different dates; underlying ownership and short-interest dates were not supplied in the table.`:'Shareholder and short-interest data unavailable for this security.'} Specialist stakes are part of institutional ownership and must not be added to it. No retail share or current trader identity is inferred. Borrow fees and utilization are unavailable.</p>
 <h3>Market behavior</h3>${stale?'<div class="notice">Price history is over seven days older than the retrieval date. Check the listing status and any corporate actions before using these technical signals.</div>':''}${spark(t.series)}<p class="definition">${t.date?`Closing-price history through ${esc(t.date)} · <a href="${esc(m.priceSource)}" target="_blank" rel="noopener">Yahoo Finance ↗</a>`:'Daily prices unavailable.'}</p><div class="detailstats">${[['Last close',t.close!=null?'$'+t.close.toFixed(2):'—'],['50D / 200D SMA',t.sma50!=null?'$'+t.sma50.toFixed(1)+' / '+(t.sma200!=null?'$'+t.sma200.toFixed(1):'—'):'—'],['RSI 14',t.rsi?.toFixed(1)??'—'],['Relative volume',t.rvol!=null?t.rvol.toFixed(2)+'×':'—']].map(([l,v])=>`<div class="metric"><label>${l}</label><strong style="font-size:19px">${v}</strong></div>`).join('')}</div><div class="twocol" style="margin-top:12px"><div>${[['1M return',signed(t.return1m)],['3M return',signed(t.return3m)],['6M return',signed(t.return6m)],['12M return',signed(t.return12m)]].map(([l,v])=>`<div class="keyval"><span>${l}</span><strong>${v}</strong></div>`).join('')}</div><div>${[['20D average dollar volume',usd(t.advDollar)],['Annualized volatility / 63D',pct(t.volatility)],['12M maximum drawdown',pct(t.maxDrawdown)],['Distance from 52W closing high',signed(t.fromHigh)]].map(([l,v])=>`<div class="keyval"><span>${l}</span><strong>${v}</strong></div>`).join('')}</div></div>
 <h3>Additional technical signals</h3><div class="detailstats">${[['MACD / signal',t.macd!=null?t.macd.toFixed(2)+' / '+t.macdSignal.toFixed(2):'—'],['ATR 14 / price',t.atr14!=null?'$'+t.atr14.toFixed(2)+' / '+pct(t.atrPercent):'—'],['Bollinger %B',pct(t.bbPercentB)],['3M relative to XLV',signed(t.relativeXLV3m).replace('%',' pp')]].map(([l,v])=>`<div class="metric"><label>${l}</label><strong style="font-size:18px">${v}</strong></div>`).join('')}</div><p class="definition">MACD uses EMA 12–26 with a 9-period signal. ATR uses Wilder smoothing over 14 sessions. Bollinger %B locates the closing price within bands at a 20-day mean ± 2 standard deviations; values can be below 0% or above 100%.</p><h3>Financial context</h3><div class="twocol"><div>${[['Market capitalization','Market Cap'],['Cash & equivalents','Cash & Cash Equivalents'],['Total debt','Total Debt']].map(([l,k])=>`<div class="keyval"><span>${l}</span><strong>${esc(stat(k))}</strong></div>`).join('')}</div><div>${[['Revenue','Revenue'],['Operating cash flow','Operating Cash Flow'],['Free cash flow','Free Cash Flow']].map(([l,k])=>`<div class="keyval"><span>${l}</span><strong>${esc(stat(k))}</strong></div>`).join('')}</div></div><p class="definition">Vendor financial periods may differ. Clinical programs, catalyst dates, cash runway estimates, beneficial-owner filings, and insider transaction histories have not been researched in this snapshot.</p><p class="definition">${s.ticker?`<a href="https://www.sec.gov/edgar/search/#/q=${encodeURIComponent(s.name)}&filter_forms=SC%252013D%252CSC%252013G%252C4%252CDEF%252014A" target="_blank" rel="noopener">Research company filings ↗</a> · <a href="https://clinicaltrials.gov/search?term=${encodeURIComponent(s.name)}" target="_blank" rel="noopener">Trial registry search ↗</a>`:''}</p></div>`;
 dialog.querySelector('#close').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog)dialog.close();};if(!dialog.open)dialog.showModal();return {ticker:s.ticker,holders:s.breadth,largestWeight:s.maxWeight};
}
function methodology(fs){return `<section class="panel"><div class="prose"><h2>A US healthcare-specialist universe</h2><p>${esc(D.selection?.selection||'Healthcare specialists with current 13F disclosure')} The dashboard tracks ${FUND_COUNT} managers; the ten tracked in its first version are all still included. Candidate fund identities and US offices were resolved against the current filing index. Portfolio size determines selection within the researched pool; this is not a ranking of investment returns.</p><p><a href="https://www.biopharmawatch.com/biotech-hedge-funds" target="_blank" rel="noopener">Specialist directory ↗</a> · <a href="https://rxdatalab.com/research/biotech-specialist-investors/" target="_blank" rel="noopener">Specialist census ↗</a></p><h2>How concentration is calculated</h2><ul><li><strong>Candidate set:</strong> the union of the five largest eligible company equity positions per fund. Widen it to the top 10, 25 or 50 positions per fund, or to all company equities. ETFs, options and warrants are excluded from candidate selection.</li><li><strong>Fund weight:</strong> reported company equity value ÷ that manager’s complete reported 13F value × 100. The denominator includes any reported option-underlying values. It is not NAV or a measure of net economic exposure.</li><li><strong>Largest allocation:</strong> the highest fund weight among the selected managers.</li><li><strong>Average across funds:</strong> sum of the company’s weights ÷ number of managers with a filing for the selected quarter. Absent positions count as zero. A large manager receives the same weight as a small manager.</li><li><strong>Holder breadth:</strong> managers disclosing the company at any size; it includes positions below the top-five cutoff. The average and breadth continue to use the whole supplied universe when one fund is selected as a candidate filter.</li><li><strong>Top appearances:</strong> number of managers in whose largest positions the company appears. All figures recalculate with the selected quarter.</li></ul><h2>Filing integrity</h2><p>Raw information tables, filing metadata and up to nine quarterly snapshots per manager are retained locally. The filing index’s effective quarterly records are used, including restatements. Historical holdings from 13f.info are SEC reproductions rounded to $1,000; direct SEC XML is used where successfully retrieved and reconciled. New-holdings amendments require explicit reconciliation before inclusion. This snapshot does not claim an independent exhaustive amendment audit.</p><p>Issuer names and CUSIPs are retained. Reviewed name corrections resolve stale symbols such as Spyre’s old AGLE identifier. Positions with different share classes are not treated as comparable share-count changes. A changed CUSIP is flagged for review. “Newly reported” is not proof of a purchase; a quarter-end weight can rise because the price rose.</p><h2>Therapeutic-area concentration</h2><p>The Sector concentration tab assigns each company equity a primary therapeutic focus from a curated ticker map in <code>data/therapeutic-areas.json</code> (oncology, immunology &amp; inflammation, neuroscience, psychedelics, metabolic/obesity, rare disease, and related buckets). Assignments are provisional research labels for specialist-ownership analysis, not GICS and not company-reported segments. Multi-franchise names use a single primary focus. Unmapped names stay Unclassified. Aggregate value and share of the current screen are recomputed for each quarter so QoQ and multi-quarter share trends can be compared.</p><h2>Market metrics</h2><p>Prices are daily closes from Yahoo Finance. Returns use adjusted close when available; moving averages and RSI use closing prices. Lookbacks: 21 / 63 / 126 / 252 trading sessions. RSI uses Wilder’s 14-session smoothing. Relative volume = latest completed daily volume ÷ mean volume of the preceding 20 sessions. Average dollar volume = mean(close × volume) over 20 sessions. Volatility = sample standard deviation of 63 daily log returns × √252. Maximum drawdown and closing high/low distances use 252 sessions. Relative benchmark returns are differences in percentage points, not risk-adjusted alpha.</p><h2>Shareholders and trading</h2><p>Institutional and insider percentages, float, short interest, days to cover, and selected financials are attributed to Stock Analysis. Their underlying observation dates are unavailable in the retrieved summary tables; retrieval date is displayed. We do not combine these with quarter-end 13F shares to produce a misleading live ownership percentage. Institutional and insider figures may overlap or use different denominators. Borrow data, named current traders, and retail ownership are unavailable.</p><p><a href="https://www.sec.gov/divisions/investment/13ffaq" target="_blank" rel="noopener">SEC Form 13F guidance ↗</a> · <a href="https://www.finra.org/finra-data/browse-catalog/short-sale-volume" target="_blank" rel="noopener">FINRA: short-sale volume is not short interest ↗</a></p><h2>Refresh and monitoring</h2><p>This is a published snapshot. Reloading the page does not fetch new filings. The included collector and market pipeline refresh the datasets; the dashboard is republished after a refresh. No recurring monitor has been scheduled. Review triggers surface overlapping large positions, unusual volume and low RSI within the selected screen.</p><p><a class="downloadlink" href="snapshot.json" download="biotech-ownership-snapshot.json">Download the complete normalized snapshot ↓</a></p></div></section><section class="panel"><div class="sectionhead"><h2>Source coverage</h2><span class="count">${fs.length} managers / ${state.period}</span></div><div class="tablewrap"><table class="sources"><thead><tr><th>Manager</th><th>Filing</th><th>Provenance</th><th>History</th></tr></thead><tbody>${fs.map(f=>`<tr><td><strong>${esc(f.name)}</strong><br>CIK ${f.cik}</td><td>${esc(f.filing.filed)}<br><a href="${esc(f.filing.xml||f.filing.sec)}" target="_blank" rel="noopener">${esc(f.filing.accession)} ↗</a></td><td>${esc(f.filing.provenance)}<br><a href="${esc(f.filing.source)}" target="_blank" rel="noopener">Readable reproduction ↗</a></td><td>${f.filings.length} quarters</td></tr>`).join('')}</tbody></table></div></section>`;}
function exportCSV(){const headers=['Ticker','Company','Quarter','Largest fund weight %','Average across funds %','Holder count','Top appearances','Combined reported value USD','Largest allocation manager','RSI 14','MACD histogram','ATR %','Bollinger %B','RVOL','3M relative XBI pp','3M relative XLV pp','Price date','Sources'];const lines=currentRows.map(s=>[s.ticker||s.key,s.name,state.period,s.maxWeight.toFixed(4),s.meanWeight.toFixed(4),s.breadth,s.topCount,s.value,s.holders[0].fundName,s.tech.rsi??'',s.tech.macdHistogram??'',s.tech.atrPercent??'',s.tech.bbPercentB??'',s.tech.rvol??'',s.tech.relativeXBI3m??'',s.tech.relativeXLV3m??'',s.tech.date??'',s.holders.map(h=>h.xml||h.sec).join(' | ')]);const csv=[headers,...lines].map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='biotech-concentration-'+state.period+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
render();
function applyData(d,v){
 const followLatest=state.period===periods[0],reopen=document.getElementById('detail')?.open?detailKey:null,y=scrollY;
 D=d;FUND_COUNT=D.expectedFunds||D.funds.length;periods=periodsOf(D);live.version=v.version;
 if(followLatest||!periods.includes(state.period))state.period=periods[0];
 render();scrollTo(0,y);if(reopen)openDetail(reopen);
 document.getElementById('announcer').textContent=lastAnnouncement='Dashboard updated with new data';
}
function loadData(v){live.loading=true;return new Promise((ok,fail)=>{const s=document.createElement('script');s.src='data.js?v='+encodeURIComponent(v.version);s.onload=()=>{s.remove();live.loading=false;applyData(window.DASHBOARD_DATA,v);ok();};s.onerror=()=>{s.remove();live.loading=false;fail(Error('New data could not be loaded'));};document.head.appendChild(s);});}
async function checkForUpdate(){
 if(document.hidden||live.loading)return;
 try{const r=await fetch('version.json?t='+Date.now(),{cache:'no-store'});if(!r.ok)throw Error(r.status);const v=await r.json();live.state='live';live.built=v.built;
  // App or stylesheet changed: full reload so open tabs pick up UI (e.g. new columns), not only data.
  if((v.app&&live.app&&v.app!==live.app)||(v.style&&live.style&&v.style!==live.style)){location.reload();return;}
  if(v.version!==(live.version??D.build))await loadData(v);live.app=v.app??live.app;live.style=v.style??live.style;}
 catch(e){live.state='offline';}
 const el=document.getElementById('livestatus');if(el)el.innerHTML=liveText();
}
if(location.protocol!=='file:'){checkForUpdate();setInterval(checkForUpdate,1000);document.addEventListener('visibilitychange',checkForUpdate);}
if(document.modelContext?.registerTool){
 document.modelContext.registerTool({name:'screen_biotech_holdings',description:'Set the visible concentration screen using the selected healthcare-specialist universe.',inputSchema:{type:'object',properties:{topPerFund:{type:'integer',enum:DEPTHS},minimumHolders:{type:'integer',enum:[1,2,3,5,10,20]},rankBy:{type:'string',enum:Object.keys(RANKINGS)}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['topPerFund','minimumHolders','rankBy'].includes(k)))throw Error('Invalid screen input');if(input.topPerFund!=null&&!DEPTHS.includes(input.topPerFund))throw Error('Invalid position cutoff');if(input.minimumHolders!=null&&![1,2,3,5,10,20].includes(input.minimumHolders))throw Error('Invalid holder count');if(input.rankBy!=null&&!Object.hasOwn(RANKINGS,input.rankBy))throw Error('Invalid ranking');Object.assign(state,{tab:'screen',depth:input.topPerFund??state.depth,min:input.minimumHolders??state.min,sort:input.rankBy??state.sort});render();return currentRows.map(s=>({ticker:s.ticker,largestWeight:s.maxWeight,medianHolderWeight:s.medianWeight,averageWeight:s.meanWeight,holders:s.breadth,qoqShareChange:s.delta}));}});
 document.modelContext.registerTool({name:'open_biotech_company',description:'Open a company profile from the current holdings quarter.',inputSchema:{type:'object',properties:{ticker:{type:'string'}},required:['ticker'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(!input||typeof input.ticker!=='string'||Object.keys(input).some(k=>k!=='ticker'))throw Error('Ticker required');const s=universe().find(s=>s.ticker===input.ticker.toUpperCase());if(!s)throw Error('Ticker unavailable in the selected quarter');return openDetail(s.key);}});
}
